SELECT path
FROM ai_memory_file
WHERE user_id=#{userId} AND delete_flag=1 AND path LIKE #{prefix}
ORDER BY path
LIMIT #{limit}

SELECT COALESCE(MAX(version),0)
FROM ai_memory_file
WHERE user_id=#{userId} AND path=#{path}

SELECT path,content
FROM ai_memory_file
WHERE user_id=#{userId} AND delete_flag=1 AND path LIKE #{prefix}
ORDER BY path
LIMIT #{limit}
